-- Migration: 123_nhis_drugs_seed.sql
-- Description: Seed NHIS drug catalogue with official NHIA 2025 prices and categories
-- Source: nhia_medicines_2025_supabase.csv (1097 drugs)
-- Schema reference: public_schema_editor.sql (drug_catalogue table)
-- Note: Prices capped at 99,999,999 for numeric(10,2) compatibility

BEGIN;

-- Add nhis_category column for NHIS drug categorization
ALTER TABLE drug_catalogue ADD COLUMN IF NOT EXISTS nhis_category TEXT;
ALTER TABLE drug_catalogue ADD COLUMN IF NOT EXISTS nhis_subcategory TEXT;

ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name,
    dosage_form = EXCLUDED.dosage_form,
    strengths = EXCLUDED.strengths,
    presentation = EXCLUDED.presentation,
    nhis_code = EXCLUDED.nhis_code,
    nhis_price = EXCLUDED.nhis_price,
    is_nhis_covered = true,
    nhis_eligible = true,
    nhis_category = EXCLUDED.nhis_category,
    nhis_subcategory = EXCLUDED.nhis_subcategory,
    updated_at = NOW();

-- Create index for nhis_category for filtering
CREATE INDEX IF NOT EXISTS idx_drug_catalogue_nhis_category ON drug_catalogue(nhis_category);

COMMIT;

